public class BSimPostgresDBConnectionManager {

	private static readonly string DRIVER_CLASS_NAME = "org.postgresql.Driver";
	private static readonly int CONN_POOL_SIZE = 2;
	private static readonly int CONN_POOL_MAX_IDLE = 2;

	private static Dictionary<BSimServerInfo, BSimPostgresDataSource> dataSourceMap = new();
	private static bool shutdownHookInstalled = false;

	public static BSimPostgresDataSource getDataSource(
			BSimServerInfo postgresServerInfo) {
		if (postgresServerInfo.getDBType() != DBType.postgres) {
			throw new IllegalArgumentException("expected postgres server info");
		}
		enableShutdownHook();
		return dataSourceMap.computeIfAbsent(postgresServerInfo,
			info => new BSimPostgresDataSource(info));
	}

	[Obsolete]
	public static BSimPostgresDataSource getDataSource(URL postgresUrl) {
		return getDataSource(new BSimServerInfo(postgresUrl));
	}

	public static BSimPostgresDataSource getDataSourceIfExists(
			BSimServerInfo serverInfo) {
		return dataSourceMap.get(serverInfo);
	}

	private static void remove(BSimServerInfo serverInfo, bool force) {
		BSimPostgresDataSource ds = dataSourceMap.get(serverInfo);
		if (ds == null) {
			return;
		}
		int n = ds.bds.getNumActive();
		if (n != 0 && !force) {
			Msg.error(typeof(BSimPostgresDBConnectionManager),
				"Unable to remove data source which has " + n + " active connections");
			return;
		}
		ds.close();
		dataSourceMap.remove(serverInfo);
	}

	private static void enableShutdownHook() {
		if (shutdownHookInstalled) {
			return;
		}
		Runtime.getRuntime().addShutdownHook(new _Anon_Thread_1());
		shutdownHookInstalled = true;
	}

	public static class BSimPostgresDataSource : BSimJDBCDataSource { // NOTE: can be renamed

		private BSimServerInfo serverInfo;

		private ConnectionType connectionType = ConnectionType.SSL_No_Authentication;
		private bool successfulConnection = false;

		private BasicDataSource bds = new BasicDataSource();
		private BSimDBConnectTaskManager taskManager;

		private BSimPostgresDataSource(BSimServerInfo serverInfo) {
