	internal class _Anon_Thread_1 : Thread
	{

			/* @Override */
			public void run() {
				Collection<BSimPostgresDataSource> dataSources = dataSourceMap.values();
				foreach (BSimPostgresDataSource ds in dataSources) {
					int activeConnections = ds.getActiveConnections();
					if (activeConnections != 0) {
						Msg.error(typeof(BSimPostgresDBConnectionManager),
							activeConnections +
								" BSim active Postgres connections were not properly closed: " +
								ds.serverInfo);
					}
					ds.close();
				}
				dataSourceMap.clear();
			}
		
